// Claude's review tests for A31/A32 in the socket editor: Error and Stream replies. agy: do not edit this file.
import { expect, test } from '@playwright/test';
import { emptyState, type Project, type SocketMock, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function sock(kind: SocketMock['kind']): SocketMock {
  return {
    id: 's', name: 'Hub', enabled: true, kind, urlPattern: '/hubs/x', createdAt: 0, onConnect: [],
    replies: [{ id: 'r', when: 'Counter', respond: 'fixed', result: '', pushes: [] }],
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function openEditor(kind: SocketMock['kind']) {
  const p: Project = { id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default', scenarios: [{ id: 'default', name: 'Default', mocks: [], sockets: [sock(kind)] }] };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  await panel.getByTestId('tab-mocks').click();
  await panel.getByTestId('socket-row').first().click();
  return { page, panel };
}

test('SignalR replies can be Error or Stream; Stream needs a JSON array', async () => {
  const { page, panel } = await openEditor('signalr');
  try {
    const respond = panel.getByTestId('reply-respond');
    await expect(respond.locator('option')).toHaveText(['Fixed', 'Code', 'Error', 'Stream']);

    await respond.selectOption('stream');
    await panel.getByTestId('reply-result').fill('[1,2');
    await expect(panel.getByTestId('reply-result-error')).toHaveText('Items must be a JSON array');
    await expect(panel.getByTestId('socket-save')).toBeDisabled();
    await panel.getByTestId('reply-result').fill('[1,2,3]');
    await expect(panel.getByTestId('reply-result-error')).toHaveCount(0);
    await panel.getByTestId('socket-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.sockets![0]!.replies[0]).toMatchObject({ respond: 'stream', result: '[1,2,3]' });

    await respond.selectOption('error');
    await panel.getByTestId('reply-result').fill('Out of stock');
    await panel.getByTestId('socket-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.sockets![0]!.replies[0]).toMatchObject({ respond: 'error', result: 'Out of stock' });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a plain socket offers only Fixed and Code', async () => {
  const { page, panel } = await openEditor('plain');
  try {
    await expect(panel.getByTestId('reply-respond').locator('option')).toHaveText(['Fixed', 'Code']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a SignalR client gets the error and the stream from the mock', async () => {
  const p: Project = {
    id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default',
    scenarios: [{ id: 'default', name: 'Default', mocks: [], sockets: [{
      ...sock('signalr'),
      replies: [
        { id: 'a', when: 'Counter', respond: 'stream', result: '[1,2,3]', pushes: [] },
        { id: 'b', when: 'Fail', respond: 'error', result: 'Out of stock', pushes: [] },
      ],
    }] }],
  };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  try {
    await page.goto(`${fixture.url}/index.html`);
    await page.addScriptTag({ url: '/signalr.js' });
    const got = await page.evaluate(async () => {
      const signalR = (window as unknown as { signalR: any }).signalR; // eslint-disable-line @typescript-eslint/no-explicit-any
      const c = new signalR.HubConnectionBuilder().withUrl(`${location.origin}/hubs/x`).configureLogging(signalR.LogLevel.None).build();
      await c.start();
      const items: number[] = [];
      await new Promise<void>((resolve, reject) => c.stream('Counter').subscribe({ next: (v: number) => items.push(v), complete: () => resolve(), error: reject }));
      let failed = '';
      try {
        await c.invoke('Fail');
      } catch (e) {
        failed = String(e);
      }
      let unknown = '';
      try {
        await c.invoke('Nope');
      } catch (e) {
        unknown = String(e);
      }
      await c.stop();
      return { items, failed, unknown };
    });
    expect(got.items).toEqual([1, 2, 3]);
    expect(got.failed).toContain('Out of stock');
    expect(got.unknown).toContain('Method does not exist');
  } finally {
    await page.close();
  }
});
